#include <iostream>
/* Function Objective: Print pass or fail for a score
   Input parameters : f_score_point (float) the score of a student
   Function description: Print pass when the score reaches the pass point, otherwise print fail
   Return Value : void
   Created By : Programmer A
   Create Date: 2026-09-28
   Revised By:
   Revised Date:
*/
void Show_Grade(float f_score_point) {
    const float PASS_POINT = 50.0f;
    bool Has_Passed = f_score_point >= PASS_POINT;
    // check whether the score reaches the pass point
    if (Has_Passed) {
        std::cout << "pass" << std::endl;
    }
    // else the score is below the pass point
    else {
        std::cout << "fail" << std::endl;
    }
}
